#include <stdio.h>

#define RB_SIZE 8

typedef struct { int data[RB_SIZE]; int head, tail; } RingBuffer;

void rb_init(RingBuffer *rb) { rb->head = 0; rb->tail = 0; }

int rb_push(RingBuffer *rb, int val) {
    int next = (rb->head + 1) % RB_SIZE;
    if (next == rb->tail) return 0;
    rb->data[rb->head] = val;
    rb->head = next;
    return 1;
}

int rb_pop(RingBuffer *rb, int *val) {
    if (rb->tail == rb->head) return 0;
    *val = rb->data[rb->tail];
    rb->tail = (rb->tail + 1) % RB_SIZE;
    return 1;
}

int main() {
    RingBuffer rb;
    rb_init(&rb);
    rb_push(&rb, 10); rb_push(&rb, 20); rb_push(&rb, 30);
    int val;
    rb_pop(&rb, &val); printf("Popped: %d\n", val);
    rb_pop(&rb, &val); printf("Popped: %d\n", val);
    return 0;
}
